import {predict,validateRecord,cleaningScenario,parseCSV,toCSV,numericFields,materials,columns,MODEL_VERSION} from './model.js';
import {rainfallWindow} from './public-data.js';
import {sampleRecords} from './sample-data.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const palette={High:'#d7665b',Moderate:'#d4a046',Low:'#4aa48b'};
let records=sampleRecords.map(r=>({...r})),selectedId=records[0].record_id,editingId=null,currentPrediction=null,pendingImport=null,importRequest=0;
let toastTimer;
function notify(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
function setView(view){if(!['overview','assessment','method'].includes(view))return;document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!=='view-'+view);document.querySelectorAll('[data-view].nav-item').forEach(b=>{const active=b.dataset.view===view;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});$('#breadcrumb').textContent={overview:'Network overview',assessment:'Assessment',method:'Data & method'}[view];window.scrollTo({top:0,behavior:'instant'});}
function badge(level){return `<span class="badge ${level.toLowerCase()}">${level} risk</span>`;}
function gauge(p){return `<div class="gauge" aria-label="${p.score} out of 100, ${p.level} screening risk"><svg viewBox="0 0 144 144" aria-hidden="true"><circle cx="72" cy="72" r="61" fill="none" stroke="#edf2f5" stroke-width="9"/><circle cx="72" cy="72" r="61" fill="none" stroke="${palette[p.level]}" stroke-width="9" stroke-linecap="round" stroke-dasharray="${p.score/100*383.27} 383.27"/></svg><div class="gauge-label"><strong>${p.score}</strong><span>RISK INDEX / 100</span></div></div>`;}
function factors(p,n=5){return p.factors.slice(0,n).map(f=>`<div class="factor-row"><div class="factor-heading"><span>${f.label}</span><strong>+${f.points.toFixed(1)} <span class="micro">/ ${f.weight}</span></strong></div><div class="factor-track"><i style="width:${f.points/f.weight*100}%"></i></div><div class="factor-detail">${esc(f.detail)}</div></div>`).join('');}
function uncertainty(r){return r.material==='Unknown'?'<p class="footnote">Material is unknown; an assumed multiplier of 0.50 is used. Confirm it before interpreting the score.</p>':'';}
function renderSelected(){const r=records.find(r=>r.record_id===selectedId)||records[0];if(!r)return;selectedId=r.record_id;const p=predict(r);$('#selected-source').textContent=r.data_source;$('#selected-result').innerHTML=`<div class="result-body">${gauge(p)}<div><h3 class="segment-title">${esc(r.location)}</h3><div class="segment-id">${esc(r.record_id)} · ${esc(r.assessment_date)}</div>${badge(p.level)}<p class="result-copy">${p.action}</p></div></div><div class="result-meta"><span>No calibrated confidence available</span><button class="text-button" id="edit-selected">Edit scenario</button></div>${uncertainty(r)}`;$('#edit-selected').addEventListener('click',()=>editRecord(r.record_id));$('#selected-factors').innerHTML=factors(p);}
function renderOverview(){const ps=records.map(predict),n=records.length,high=ps.filter(p=>p.level==='High').length,avg=Math.round(ps.reduce((a,p)=>a+p.score,0)/n),overdue=records.filter(r=>r.days_since_cleaning>180).length;
const stats=[['Segments assessed',n,'Current session records','▤',100,''],['High risk',high,'Score of 65 or higher','△',high/n*100,'high-stat'],['Average risk index',avg,'Across current records','◴',avg,''],['Cleaning delay >180 days',overdue,'Illustrative review threshold','◷',overdue/n*100,'']];
$('#stats').innerHTML=stats.map(([label,value,detail,icon,width,cls])=>`<article class="stat ${cls}"><div class="stat-top"><span>${label}</span><span class="stat-icon" aria-hidden="true">${icon}</span></div><div class="stat-value">${value}${label==='Average risk index'?'<small> / 100</small>':''}</div><div class="stat-detail">${detail}</div><div class="stat-meter"><i style="width:${width}%"></i></div></article>`).join('');
const allSynthetic=records.every(r=>r.data_source==='Synthetic sample');$('#dataset-label').textContent=allSynthetic?'Synthetic demonstration data':'Session assessment data';$('#dataset-desc').textContent=allSynthetic?`${n} synthetic scenarios. Locality names are context only; these are not real municipal records.`:`${n} records with self-reported provenance. Inputs have not been independently verified.`;renderSelected();renderTable();}
function renderTable(){const q=$('#search').value.trim().toLowerCase(),level=$('#risk-filter').value;const filtered=records.map(r=>({r,p:predict(r)})).filter(({r,p})=>(r.record_id+' '+r.location).toLowerCase().includes(q)&&(level==='All'||level===p.level)).sort((a,b)=>b.p.score-a.p.score);$('#record-count').textContent=records.length;$('#table-summary').textContent=filtered.length+' of '+records.length+' records';$('#records-body').innerHTML=filtered.length?filtered.map(({r,p})=>`<tr class="${r.record_id===selectedId?'selected':''}"><td><button class="record-link" data-select="${esc(r.record_id)}">${esc(r.location)}<small>${esc(r.record_id)}</small></button></td><td><div class="score-cell"><strong>${p.score}</strong><span class="mini-track"><i style="width:${p.score}%;background:${palette[p.level]}"></i></span></div></td><td>${badge(p.level)}</td><td>${r.days_since_cleaning} days ago</td><td>${r.previous_blockages_12m} events</td><td><span class="badge source-badge">${esc(r.data_source)}</span></td><td><button class="text-button" data-edit="${esc(r.record_id)}" aria-label="Edit ${esc(r.record_id)}">Edit</button></td></tr>`).join(''):'<tr><td colspan="7" class="empty-table">No records match this search. Try another location or risk level.</td></tr>';
$('#records-body').querySelectorAll('[data-select]').forEach(b=>b.addEventListener('click',()=>{selectedId=b.dataset.select;renderSelected();renderTable();}));$('#records-body').querySelectorAll('[data-edit]').forEach(b=>b.addEventListener('click',()=>editRecord(b.dataset.edit)));}
const assetKeys=['previous_blockages_12m','cleanings_12m','days_since_cleaning','pipe_age_years','diameter_mm'];
function numberField(k){const d=numericFields[k];const help={previous_blockages_12m:'Verified incidents before the assessment date',cleanings_12m:'Completed cleanings, not planned visits',days_since_cleaning:'Assessment date minus last completed cleaning',pipe_age_years:'Assessment year minus installation year',diameter_mm:'Internal diameter in millimetres',rainfall_7d_mm:'Total over 7 days before the assessment',flooding_events_12m:'Local incidents; flooding may have other causes',population_per_km2:'People per km² in the sewer catchment',commercial_sites_per_km2:'Shops, restaurants and other commercial sites per km²'};return `<label>${d.label}<input type="number" name="${k}" required min="${d.min}" max="${d.max}" step="${d.integer?'1':'any'}" placeholder="Enter a value"><small>${help[k]}</small></label>`;}
$('#asset-fields').innerHTML=assetKeys.map(numberField).join('')+`<label>Pipe material<select name="material">${materials.map(m=>'<option>'+m+'</option>').join('')}</select><small>Use Unknown only when the material is unavailable</small></label>`;$('#context-fields').innerHTML=Object.keys(numericFields).filter(k=>!assetKeys.includes(k)).map(numberField).join('');
function fillForm(r){for(const k of columns){const el=$('#assessment-form').elements.namedItem(k);if(el)el.value=r[k]??'';}}
function resetOutput(){currentPrediction=null;$('#form-result').innerHTML='<div class="empty-result"><span class="empty-icon">◎</span><h2>Your assessment appears here</h2><p>Fill in every input and calculate risk to see a score, contributing factors, and a cleaning scenario.</p><span class="badge source-badge">Transparent screening model</span></div>';$('#form-errors').hidden=true;}
function beginAssessment(){editingId=null;$('#assessment-form').reset();$('#assessment-form').elements.assessment_date.value=new Date().toISOString().slice(0,10);$('#form-heading').textContent='New assessment';resetOutput();setView('assessment');}
function editRecord(id){const r=records.find(r=>r.record_id===id);if(!r)return;editingId=id;fillForm(r);$('#form-heading').textContent='Edit assessment';resetOutput();setView('assessment');}
function renderFormResult(p){currentPrediction=p;const r=p.record,after=cleaningScenario(r),delta=p.score-after.score;$('#form-result').innerHTML=`<div class="output-top"><span class="badge source-badge">${esc(r.data_source)}</span><h2 class="segment-title" style="margin-top:14px">${esc(r.location)}</h2><div class="segment-id">${esc(r.record_id)} · ${esc(r.assessment_date)}</div>${gauge(p)}${badge(p.level)}<p>${p.action}</p></div><h3 class="output-heading">Main contributing factors</h3>${factors(p,5)}<details><summary>Show all 10 contributions</summary><div style="margin-top:18px">${factors(p,10)}</div></details>${uncertainty(r)}<div class="scenario-box"><h3>What if cleaning is brought up to date?</h3><div class="scenario-numbers"><span>${p.score}</span><span style="font-size:14px;color:#79928b">→</span><span>${after.score} <small>(${delta} points lower)</small></span></div><p>Resets days since cleaning to 0 and assumes at least 4 cleanings/year. Other inputs stay fixed. This is a score comparison, not a forecast of maintenance benefit.</p></div><button class="button primary" id="add-record" style="width:100%">${editingId?'Update session record':'Add to session records'}</button><p class="footnote">No calibrated confidence available. Export your records before leaving; this session is not saved.</p>`;$('#add-record').addEventListener('click',saveRecord);}
function saveRecord(){if(!currentPrediction)return;const r=currentPrediction.record;if(records.some(x=>x.record_id===r.record_id&&x.record_id!==editingId)){notify('That record ID already exists. Use a unique ID.');return;}if(editingId)records=records.filter(x=>x.record_id!==editingId);records.push({...r});selectedId=r.record_id;renderOverview();setView('overview');notify('Assessment added to this session. Export results to keep it.');editingId=null;}
$('#assessment-form').addEventListener('submit',e=>{e.preventDefault();$('#form-errors').hidden=true;try{const input=Object.fromEntries(new FormData(e.currentTarget));renderFormResult(predict(input));}catch(e){$('#form-errors').textContent=e.message;$('#form-errors').hidden=false;resetOutput();$('#form-errors').textContent=e.message;$('#form-errors').hidden=false;}});
// Changing any input invalidates the old result, so stale predictions cannot be added.
$('#assessment-form').addEventListener('input',()=>{if(currentPrediction)resetOutput();});$('#assessment-form').addEventListener('change',()=>{if(currentPrediction)resetOutput();});
$('#fill-example').addEventListener('click',()=>{editingId=null;fillForm({...sampleRecords[0],record_id:'SCENARIO-'+Date.now().toString().slice(-6),location:'Chennai · test scenario'});$('#form-heading').textContent='New assessment';resetOutput();notify('Synthetic inputs loaded. Edit them and calculate risk.');});
function download(name,content){const url=URL.createObjectURL(new Blob(['\uFEFF'+content],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function downloadTemplate(){download('al-sewer-input-template.csv',columns.join(',')+'\r\n');notify('Template downloaded. See Data & method for units and source labels.');}
$('#export-results').addEventListener('click',()=>{download('al-sewer-risk-results.csv',toCSV(records,true));notify('Results exported with risk scores, provenance and model version.');});$('#download-sample').addEventListener('click',()=>download('al-sewer-synthetic-sample.csv',toCSV(sampleRecords)));['download-template','dialog-template'].forEach(id=>$('#'+id).addEventListener('click',downloadTemplate));
$('#load-samples').addEventListener('click',()=>{records=sampleRecords.map(r=>({...r}));selectedId=records[0].record_id;$('#search').value='';$('#risk-filter').value='All';renderOverview();notify('Sample dataset restored. These 12 records are synthetic.');});
function openImport(){pendingImport=null;importRequest++;$('#csv-file').value='';$('#import-preview').hidden=true;$('#import-message').hidden=true;$('#confirm-import').disabled=true;$('#import-dialog').showModal();}
$('#open-import').addEventListener('click',openImport);$('#close-import').addEventListener('click',()=>$('#import-dialog').close());
$('#csv-file').addEventListener('change',async e=>{const request=++importRequest,file=e.target.files[0];pendingImport=null;$('#confirm-import').disabled=true;$('#import-message').hidden=true;$('#import-preview').hidden=true;if(!file)return;try{if(file.size>2*1024*1024)throw new Error('CSV must be smaller than 2 MB.');const rows=parseCSV(await file.text());if(request!==importRequest)return;pendingImport=rows;const high=rows.map(predict).filter(p=>p.level==='High').length;$('#import-preview').innerHTML=`<strong>${rows.length} valid records ready</strong><small>${high} high-risk scenarios. Data sources: ${esc([...new Set(rows.map(r=>r.data_source))].join(', '))}.</small>`;$('#import-preview').hidden=false;$('#confirm-import').disabled=false;}catch(error){if(request!==importRequest)return;$('#import-message').textContent=error.message;$('#import-message').className='error';$('#import-message').hidden=false;}});
function importRecords(rows){if(!Array.isArray(rows)||!rows.length||rows.length>1000)throw new Error('Provide 1–1,000 valid records.');const validated=[],ids=new Set();for(const input of rows){const v=validateRecord(input);if(v.errors.length)throw new Error(v.errors.join('\n'));if(ids.has(v.record.record_id))throw new Error('Duplicate record ID: '+v.record.record_id);ids.add(v.record.record_id);validated.push(v.record);}records=validated;selectedId=records[0].record_id;$('#search').value='';$('#risk-filter').value='All';renderOverview();setView('overview');return {record_count:records.length,high_risk_count:records.map(predict).filter(p=>p.level==='High').length};}
$('#confirm-import').addEventListener('click',()=>{if(!pendingImport)return;const count=pendingImport.length;importRecords(pendingImport);$('#import-dialog').close();pendingImport=null;notify(count+' records imported into this session.');});
$('#search').addEventListener('input',renderTable);$('#risk-filter').addEventListener('change',renderTable);
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.view==='assessment')beginAssessment();else setView(b.dataset.view);}));$('#new-assessment').addEventListener('click',beginAssessment);
const definitions=[['Repeated blockages',22,'blockages / 5'],['Time since cleaning',14,'days / 365'],['Cleaning frequency',4,'1 − cleanings / 4'],['Pipe age',10,'years / 50'],['Pipe diameter',8,'(600 − mm) / 500'],['Pipe material',8,'assumed multiplier (see below)'],['Recent rainfall',14,'7-day rainfall / 150'],['Flooding history',10,'events / 4'],['Population density',6,'people per km² / 25,000'],['Commercial density',4,'sites per km² / 150']];
$('#weight-table').innerHTML=definitions.map(([label,w,norm])=>`<tr><td>${label}</td><td>${w}</td><td>${norm}</td></tr>`).join('');$('#csv-columns').textContent=columns.join(', ');renderOverview();
// Browser WebMCP is optional. Actions share UI validation and visible session state.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
register({name:'import_sewer_assessment_csv',title:'Import assessment CSV',description:'Validate CSV records and replace the visible session dataset. No durable storage. Throws on invalid input without changing records.',inputSchema:{type:'object',properties:{csv:{type:'string',maxLength:2097152}},required:['csv'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:input=>{if(!input||typeof input.csv!=='string'||Object.keys(input).some(k=>k!=='csv'))throw new Error('Provide only the csv text.');return importRecords(parseCSV(input.csv));}});
register({name:'read_sewer_assessment_results',title:'Read current risk scores',description:'Read the screening scores and provenance of the current session records. Does not modify state.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:input=>{if(!input||Object.keys(input).length)throw new Error('No input fields are accepted.');return records.map(r=>{const p=predict(r);return {record_id:r.record_id,location:r.location,data_source:r.data_source,score:p.score,level:p.level,main_factors:p.factors.slice(0,3).map(f=>({factor:f.label,points:Number(f.points.toFixed(1))})),model_version:MODEL_VERSION};});}});
window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}

let publicRainfall=null, publicSewers=null, currentRainfall=null;
function publicAssetPreview(){const a=publicSewers.assets[Number($('#public-asset').value)];if(!a)return;$('#asset-preview').innerHTML=`<div class="public-preview"><strong>${esc(a.asset_id)}</strong> · ${esc(a.road_name)}<br>Area ${esc(a.area)} / depot ${esc(a.depot)}<br><strong>${a.diameter_mm} mm</strong> · ${esc(a.source_material)}<br><span class="footnote">Source material code ${esc(a.material_code)} · size code ${esc(a.size_code)}<br>Age, cleaning and blockage histories: unavailable in this file.</span></div>`;}
function publicRainPreview(){try{currentRainfall=rainfallWindow(publicRainfall,$('#public-station').value,$('#public-date').value);const r=currentRainfall;$('#rainfall-preview').innerHTML=`<div class="public-preview ${r.complete?'':'warning'}"><div class="rain-number">${r.sum_mm} <small>mm ${r.complete?'over 7 days':'on observed days only'}</small></div><div class="daily-readings">${r.readings.map(d=>`<span>${d.date.slice(5)}<strong>${d.status==='observed'?d.value+' mm':d.status}</strong></span>`).join('')}</div><p class="footnote">${r.observed_days}/7 days observed. ${r.complete?'All daily readings available for this window.':'Incomplete window — cannot use it as a 7-day total.'}</p></div>`;$('#use-public-rainfall').disabled=!r.complete;}catch(e){currentRainfall=null;$('#rainfall-preview').textContent=e.message;$('#use-public-rainfall').disabled=true;}}
async function loadPublicData(){try{const [rain,sewers]=await Promise.all(['data/chennai-rainfall-index.json','data/chennai-sewer-subset.json'].map(async path=>{const r=await fetch(path);if(!r.ok)throw new Error('Source snapshot is unavailable.');return r.json();}));publicRainfall=rain;publicSewers=sewers;$('#public-station').innerHTML=Object.keys(rain.stations).map(st=>`<option>${esc(st)}</option>`).join('');$('#public-station').value=rain.meta.default_station;$('#public-date').value=rain.meta.default_date;$('#public-asset').innerHTML=sewers.assets.map((a,i)=>`<option value="${i}">${esc(a.asset_id)} · ${esc(a.road_name)} (${a.diameter_mm} mm)</option>`).join('');$('#public-meta').textContent=`${sewers.meta.subset_count} public sewer features in this subset · ${rain.meta.raw_rows.toLocaleString('en-IN')} raw rainfall readings · ${rain.meta.station_count} station names. Retrieved ${rain.meta.retrieved}. This is historical source data, not a live feed.`;$('#source-notes').innerHTML=`<p><strong>Assets:</strong> ${sewers.meta.sampling} ${sewers.meta.source_features.toLocaleString('en-IN')} source features were parsed. Material and size codes use the companion dictionary. ${sewers.meta.unmapped_source_features.toLocaleString('en-IN')} source features with unrecognised codes are excluded from the selectable subset. Brick Arch → Brick, RCC Pipe → Concrete, CI Pipe → Cast iron, PVC/PVC Pipe → PVC; other source labels stay as written.</p><p><strong>Rainfall:</strong> Raw rows: ${rain.meta.raw_rows.toLocaleString('en-IN')}; unique station-days: ${rain.meta.unique_station_days.toLocaleString('en-IN')}; extra duplicate/conflicting rows: ${rain.meta.duplicate_extra_rows.toLocaleString('en-IN')}; conflicting station-days: ${rain.meta.conflicting_station_days}. Exact duplicates collapse; conflicting readings are excluded. No absent date is filled with zero. Although the resource title says 1991–2023, this downloaded snapshot runs from ${rain.meta.min_date} to ${rain.meta.max_date} and is sparse. Station names are not merged.</p><p><strong>Limit:</strong> Public pipe geometry does not provide age, dated cleaning, blockages, flood incidents or density in these files. Station rainfall is an approximation for a sewer catchment. Combining historical rain with current assets requires explicit assumptions. This data cannot establish predictive accuracy.</p><p><a href="${esc(sewers.meta.source_url)}" target="_blank" rel="noopener noreferrer">CMWSSB sewer collection dataset on OpenCity</a> · <a href="${esc(rain.meta.source_url)}" target="_blank" rel="noopener noreferrer">TNDMA-attributed rainfall resource on OpenCity</a></p><p><a href="data/chennai-daily-rainfall.csv" download>Download unmodified rainfall CSV</a> · <a href="data/chennai-sewer-subset.json" download>Download extracted sewer subset</a> · <a href="data/chennai-sewer-codes.txt" download>Download source code dictionary</a></p><p>Both portals list Other (Public Domain). Original providers: CMWSSB GIS for sewer features; TNDMA attribution for daily rainfall. Source URLs, retrieval dates, file hashes and transformations are recorded in the downloadable JSON files.</p>`;$('#public-loading').hidden=true;$('#chennai-explorer').hidden=false;publicAssetPreview();publicRainPreview();}catch(e){$('#public-loading').textContent='Could not load the Chennai snapshot. Your assessments still work. Reload to retry, or follow the linked sources in the guide.';}}
$('#public-asset').addEventListener('change',publicAssetPreview);$('#public-station').addEventListener('change',publicRainPreview);$('#public-date').addEventListener('change',publicRainPreview);
$('#use-public-asset').addEventListener('click',()=>{const a=publicSewers?.assets[Number($('#public-asset').value)];if(!a)return;beginAssessment();const f=$('#assessment-form').elements;f.record_id.value='CHN-'+a.source_objectid;f.location.value=a.road_name+', Chennai (depot '+a.depot+')';f.material.value=a.model_material;f.diameter_mm.value=a.diameter_mm;f.data_source.value='Mixed / estimated';f.source_note.value='Public asset '+a.asset_id+' (objectid '+a.source_objectid+') from OpenCity/CMWSSB GIS; diameter and material decoded from source codes. Remaining inputs must be supplied and documented. Snapshot retrieved 2026-10-06.';notify('Real location, material and diameter loaded. Fill the missing history and context.');});
$('#use-public-rainfall').addEventListener('click',()=>{if(!currentRainfall?.complete)return;const r=currentRainfall;const f=$('#assessment-form').elements;if(!f.record_id.value){beginAssessment();f.record_id.value='CHN-RAIN-'+Date.now().toString().slice(-6);f.location.value=r.station+', Chennai';}f.assessment_date.value=r.assessment_date;f.rainfall_7d_mm.value=r.sum_mm;f.data_source.value='Mixed / estimated';f.source_note.value=(f.source_note.value+' Rainfall: '+r.sum_mm+' mm in 7 observed days before '+r.assessment_date+', station '+r.station+'; TNDMA-attributed OpenCity CSV. Other inputs need provenance.').trim().slice(0,500);resetOutput();setView('assessment');notify('Public rainfall applied. Check that the station and historical date fit your sewer record.');});
loadPublicData();
